import com.sun.net.httpserver.*;import java.net.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
/** Servidor HTTP local. A sessão identifica a conta de demonstração e o Java aplica as permissões. */
public class Servidor {
    private SistemaEscolar s;private final Repositorio repo;private final Map<String,Usuario> sessoes=new HashMap<>();private final Map<String,Long> expiracoes=new HashMap<>();private final String conviteProfessor=System.getenv("PROFESSOR_INVITE");private boolean indisponivel=false;
    private Servidor(Path arquivo)throws IOException{repo=new Repositorio(arquivo);if(repo.online()&&(conviteProfessor==null||conviteProfessor.length()<16))throw new IOException("Configure PROFESSOR_INVITE com pelo menos 16 caracteres.");s=repo.carregar();}
    public static void main(String[] args)throws Exception{int porta=args.length>0?Integer.parseInt(args[0]):Integer.parseInt(System.getenv().getOrDefault("PORT","8080"));Path dados=Path.of(args.length>1?args[1]:"dados/servidor.json");Servidor app=new Servidor(dados);HttpServer h=HttpServer.create(new InetSocketAddress("0.0.0.0",porta),0);h.createContext("/api/",app::api);h.createContext("/health",app::health);h.createContext("/",app::statico);h.start();System.out.println("Gestão Escolar — http://localhost:"+porta+" | Persistência: "+(app.repo.online()?"PostgreSQL":"JSON local"));}
    private synchronized void health(HttpExchange e)throws IOException{json(e,indisponivel?503:200,Json.obj("ok",!indisponivel,"storage",repo.online()?"postgresql":"json-local"));}
    private void persistir()throws IOException{try{repo.salvar(s);}catch(IOException ex){sessoes.clear();expiracoes.clear();try{s=repo.carregar();}catch(Exception falha){indisponivel=true;}throw ex;}}
    private void enviar(HttpExchange e,int code,String tipo,byte[] bytes)throws IOException{e.getResponseHeaders().set("Content-Type",tipo);e.getResponseHeaders().set("X-Content-Type-Options","nosniff");e.getResponseHeaders().set("Cache-Control","no-store");e.sendResponseHeaders(code,bytes.length);try(OutputStream os=e.getResponseBody()){os.write(bytes);}}
    private void json(HttpExchange e,int code,Object o)throws IOException{enviar(e,code,"application/json; charset=utf-8",Json.stringify(o).getBytes(StandardCharsets.UTF_8));}
    private void statico(HttpExchange e)throws IOException{String p=e.getRequestURI().getPath();if(p.equals("/"))p="/index.html";Map<String,String> arquivos=Map.of("/index.html","text/html; charset=utf-8","/app.js","text/javascript; charset=utf-8","/style.css","text/css; charset=utf-8","/manifest.webmanifest","application/manifest+json","/sw.js","text/javascript; charset=utf-8","/icon.svg","image/svg+xml","/icon-192.png","image/png","/icon-512.png","image/png");if(!e.getRequestMethod().equals("GET")||!arquivos.containsKey(p)){json(e,404,Json.obj("erro","Não encontrado."));return;}try(InputStream in=Servidor.class.getResourceAsStream("/web"+p)){if(in==null){json(e,404,Json.obj("erro","Arquivo indisponível."));return;}enviar(e,200,arquivos.get(p),in.readAllBytes());}}
    private static Map<String,Object> user(Usuario u){return u==null?null:Json.obj("id",u.getId(),"nome",u.getNome(),"perfil",u.getPerfil().name());}
    private static String t(Map<String,Object> m,String k){return Json.str(m,k);}private static int n(Map<String,Object> m,String k){return Json.num(m,k);}private static boolean b(Map<String,Object> m,String k){return Json.bool(m,k);}
    private static LocalDateTime hora(Map<String,Object> m){return LocalDateTime.parse(t(m,"horario"));}
    private Map<String,Object> equipe(Usuario u,Equipe e){boolean interno=u.isProfessor()||e.temMembro(u),nome=interno||e.isNomePublico();return Json.obj("id",e.getId(),"nome",nome?e.getNome():null,"descricao",interno||e.isPublica()?e.getDescricao():null,"foto",nome?e.getFoto():null,"lider",interno||e.isLiderPublico()?user(e.getLider()):null,"membros",interno||e.isMembrosPublicos()?e.getMembros().stream().map(Servidor::user).collect(java.util.stream.Collectors.toList()):null,"publica",e.isPublica(),"nomePublico",e.isNomePublico(),"liderPublico",e.isLiderPublico(),"membrosPublicos",e.isMembrosPublicos(),"souLider",e.ehLider(u),"souMembro",e.temMembro(u));}
    private Object estado(Usuario u){List<Object> as=new ArrayList<>(),es=new ArrayList<>(),ps=new ArrayList<>(),ms=new ArrayList<>(),cs=new ArrayList<>();for(Atividade a:s.atividadesDe(u)){List<Object> ents=new ArrayList<>();for(Entrega e:a.getEntregas())if(u.isProfessor()||e.getAluno()==u)ents.add(Json.obj("aluno",user(e.getAluno()),"resposta",e.getResposta(),"data",e.getData().toString()));as.add(Json.obj("id",a.getId(),"titulo",a.getTitulo(),"materia",a.getMateria(),"descricao",a.getDescricao(),"prazo",a.getPrazo().toString(),"professor",user(a.getProfessor()),"turma",a.getTurma(),"turmaNome",s.academico.nomeTurma(a.getTurma()),"status",u.isProfessor()?"PUBLICADA":a.status(u,LocalDate.now()),"entregas",ents));}for(Equipe e:s.equipesVisiveis(u))es.add(equipe(u,e));for(Projeto p:s.projetosVisiveis(u)){Equipe e=p.getEquipe();boolean vis=s.podeVerEquipe(u,e);boolean nome=u.isProfessor()||e.temMembro(u)||(vis&&e.isNomePublico());ps.add(Json.obj("id",p.getId(),"nome",p.getNome(),"descricao",p.getDescricao(),"equipe",vis?e.getId():null,"equipeNome",nome?e.getNome():null,"mentor",user(p.getMentor()),"publico",p.isPublico(),"souLider",e.ehLider(u),"souMembro",e.temMembro(u),"souMentor",p.getMentor()==u));}for(Mentoria m:s.mentoriasDe(u))ms.add(Json.obj("id",m.getId(),"projeto",m.getProjeto().getId(),"projetoNome",m.getProjeto().getNome(),"professor",user(m.getProfessor()),"assunto",m.getAssunto(),"horario",m.getHorario().toString(),"status",m.getStatus().name(),"souLider",m.getProjeto().getEquipe().ehLider(u)));if(!u.isProfessor())for(Equipe e:s.convitesDe(u))cs.add(Json.obj("id",e.getId(),"nome",e.isPublica()&&e.isNomePublico()?e.getNome():"Convite de equipe privada","lider",user(e.getLider())));Map<String,Object> resultado=Json.obj("usuario",user(u),"usuarios",s.getUsuarios().stream().map(Servidor::user).collect(java.util.stream.Collectors.toList()),"atividades",as,"equipes",es,"projetos",ps,"mentorias",ms,"convites",cs);resultado.putAll(s.academico.estado(u));return resultado;}
    private synchronized void api(HttpExchange e)throws IOException{try{if(indisponivel){json(e,503,Json.obj("erro","Servidor indisponível. Reinicie o serviço."));return;}String path=e.getRequestURI().getPath(),method=e.getRequestMethod();if(path.equals("/api/cadastro")&&method.equals("POST")){Map<String,Object> m=body(e);if(repo.online()&&t(m,"perfil").equals("PROFESSOR")&&!java.security.MessageDigest.isEqual(conviteProfessor.getBytes(StandardCharsets.UTF_8),t(m,"codigo").getBytes(StandardCharsets.UTF_8)))throw new IllegalArgumentException("Código de autorização do professor inválido.");s.cadastrar(t(m,"perfil"),t(m,"email"),t(m,"login"),t(m,"senha"),t(m,"codigo"));persistir();json(e,201,Json.obj("ok",true));return;}if(path.equals("/api/login")&&method.equals("POST")){Map<String,Object> m=body(e);Usuario u=s.autenticar(t(m,"perfil"),t(m,"identificador"),t(m,"senha"));if(u==null){json(e,401,Json.obj("erro","Credenciais inválidas."));return;}String token=UUID.randomUUID().toString();long agora=System.currentTimeMillis();expiracoes.entrySet().removeIf(x->{if(x.getValue()<agora){sessoes.remove(x.getKey());return true;}return false;});if(sessoes.size()>=1000){json(e,503,Json.obj("erro","Limite de sessões atingido."));return;}sessoes.put(token,u);expiracoes.put(token,agora+8*60*60*1000L);json(e,200,Json.obj("token",token,"estado",estado(u)));return;}String auth=e.getRequestHeaders().getFirst("Authorization");String token=auth!=null&&auth.startsWith("Bearer ")?auth.substring(7):"";Usuario u=sessoes.get(token);if(u==null||expiracoes.getOrDefault(token,0L)<System.currentTimeMillis()){json(e,401,Json.obj("erro","Sessão encerrada. Entre novamente."));return;}if(path.equals("/api/estado")&&method.equals("GET")){json(e,200,estado(u));return;}if(path.equals("/api/logout")&&method.equals("POST")){sessoes.remove(token);expiracoes.remove(token);json(e,200,Json.obj("ok",true));return;}if(path.equals("/api/codigo")&&method.equals("POST")){String c=s.emitirCodigo(u);persistir();json(e,200,Json.obj("codigo",c));return;}if(path.equals("/api/material")&&method.equals("POST")){byte[] pdf=s.academico.baixar(u,n(body(e),"id"));e.getResponseHeaders().set("Content-Disposition","attachment; filename=material.pdf");enviar(e,200,"application/pdf",pdf);return;}if(!path.equals("/api/acao")||!method.equals("POST")){json(e,404,Json.obj("erro","Rota inexistente."));return;}Map<String,Object> m=body(e);switch(t(m,"acao")){
        case "atividade":{int tid=m.containsKey("turma")?n(m,"turma"):0;if(tid==0&&repo.online())throw new IllegalArgumentException("Selecione uma turma para publicar a atividade.");String materia=tid==0?t(m,"materia"):s.academico.materiaDaTurma(u,tid);Atividade a=s.cadastrarAtividade(u,t(m,"titulo"),materia,t(m,"descricao"),LocalDate.parse(t(m,"prazo")));a.definirTurma(tid);break;}
        case "criarMateria":s.academico.criarMateria(u,t(m,"nome"));break;
        case "criarTurma":s.academico.criarTurma(u,n(m,"materia"),t(m,"nome"));break;
        case "adicionarAluno":s.academico.adicionarAluno(u,n(m,"id"),n(m,"aluno"));break;
        case "removerAluno":s.academico.removerAluno(u,n(m,"id"),n(m,"aluno"));break;
        case "criarPasse":{String codigo=s.academico.criarPasse(u,n(m,"id"),t(m,"nome"),t(m,"matricula"),t(m,"nascimento"));persistir();Map<String,Object> res=Json.obj("codigo",codigo,"estado",estado(u));json(e,200,res);return;}
        case "cancelarPasse":s.academico.cancelarPasse(u,n(m,"id"));break;
        case "publicarMaterial":s.academico.publicar(u,n(m,"turma"),t(m,"titulo"),t(m,"descricao"),t(m,"link"),t(m,"arquivo"),t(m,"base64"));break;
        case "excluirMaterial":s.academico.excluirMaterial(u,n(m,"id"));break;
        case "entregar":s.entregar(u,s.atividade(n(m,"id")),t(m,"resposta"));break;
        case "criarEquipe":{boolean pub=b(m,"publica"),np=b(m,"nomePublico"),lp=b(m,"liderPublico"),mp=b(m,"membrosPublicos");Equipe eq=s.criarEquipe(u,t(m,"nome"),t(m,"descricao"),t(m,"foto"));s.privacidadeEquipe(u,eq,pub,np,lp,mp);break;}
        case "editarEquipe":{Equipe eq=s.equipe(n(m,"id"));boolean pub=b(m,"publica"),np=b(m,"nomePublico"),lp=b(m,"liderPublico"),mp=b(m,"membrosPublicos");s.editarEquipe(u,eq,t(m,"nome"),t(m,"descricao"),t(m,"foto"));s.privacidadeEquipe(u,eq,pub,np,lp,mp);break;}
        case "transferirLider":s.transferirLider(u,s.equipe(n(m,"id")),s.usuario(n(m,"aluno")));break;
        case "convidar":s.convidar(u,s.equipe(n(m,"id")),s.usuario(n(m,"aluno")));break;
        case "convite":s.responderConvite(u,s.equipe(n(m,"id")),b(m,"aceitar"));break;
        case "criarProjeto":{boolean pub=b(m,"publico");Projeto p=s.criarProjeto(u,s.equipe(n(m,"equipe")),t(m,"nome"),t(m,"descricao"));s.privacidadeProjeto(u,p,pub);break;}
        case "privacidadeProjeto":s.privacidadeProjeto(u,s.projeto(n(m,"id")),b(m,"publico"));break;
        case "orientar":s.orientar(u,s.projeto(n(m,"id")));break;
        case "solicitar":s.solicitarMentoria(u,s.projeto(n(m,"id")),t(m,"assunto"),hora(m));break;
        case "agendar":s.agendarMentoria(u,s.projeto(n(m,"id")),t(m,"assunto"),hora(m));break;
        case "responderMentoria":{int dec=n(m,"decisao");s.responderMentoria(u,s.mentoria(n(m,"id")),dec,dec==3?hora(m):null);break;}
        case "reagendamento":s.responderReagendamento(u,s.mentoria(n(m,"id")),b(m,"aceitar"));break;
        default:throw new IllegalArgumentException("Operação desconhecida.");}
        persistir();json(e,200,estado(u));
    }catch(IllegalArgumentException|java.time.DateTimeException ex){json(e,400,Json.obj("erro",ex.getMessage()==null?"Entrada inválida.":ex.getMessage()));}catch(IOException ex){System.err.println("Falha de persistência ou comunicação: "+ex.getClass().getSimpleName());json(e,503,Json.obj("erro","Não foi possível confirmar a gravação. Entre novamente e confira os dados."));}catch(Exception ex){System.err.println("Falha interna: "+ex.getClass().getSimpleName());json(e,500,Json.obj("erro","Falha interna; verifique o terminal do servidor."));}}
    private Map<String,Object> body(HttpExchange e)throws IOException{int max=e.getRequestURI().getPath().equals("/api/acao")?3*1024*1024:65536;byte[] bytes=e.getRequestBody().readNBytes(max+1);if(bytes.length>max)throw new IllegalArgumentException("Solicitação muito grande.");Object o=Json.parse(new String(bytes,StandardCharsets.UTF_8));if(!(o instanceof Map))throw new IllegalArgumentException("JSON inválido.");return Json.map(o);}
}
